  str_season_mission_desc_8001001 = "En ese momento, un repentino estallido de golpes apresurados resonó en el aire, despertando a Eve de su extraño y fantástico sueño...",
  str_season_mission_desc_8001002 = "En ese momento, un repentino estallido de golpes apresurados resonó en el aire, despertando a Eve de su extraño y fantástico sueño...",
  str_season_mission_desc_8001003 = "¿Quién podría ser esta enigmática sombra y qué la impulsa a destruir el preciado bloc de dibujo de Eve?",
  str_season_mission_desc_8001004 = "¿Quién podría ser esta enigmática sombra y qué la impulsa a destruir el preciado bloc de dibujo de Eve?",
  str_season_mission_desc_8001005 = "¿Qué hace que la sombra huya? Cuanto más huye, más fuerte se vuelve el impulso de Eve para buscar y desentrañar el misterio.",
  str_season_mission_desc_8001006 = "¿Qué hace que la sombra huya? Cuanto más huye, más fuerte se vuelve el impulso de Eve para buscar y desentrañar el misterio.",
  str_season_mission_desc_8001007 = "¡Rayos! ¡La sombra ha logrado meterse en un callejón estrecho! ¡No hay manera de que la deje escapar así!",
  str_season_mission_desc_8001008 = "¡Rayos! ¡La sombra ha logrado meterse en un callejón estrecho! ¡No hay manera de que la deje escapar así!",
  str_season_mission_desc_8001009 = "Por fin, Eve alcanzó a la sombra al final del estrecho callejón, solo para descubrir que la sombra era, de hecho...",
  str_season_mission_desc_8001010 = "Por fin, Eve alcanzó a la sombra al final del estrecho callejón, solo para descubrir que la sombra era, de hecho...",
  str_season_mission_desc_8001011 = "Después de sus ocupadas actividades, la sedienta Eve se dirigió al pozo para beber, pero notó algo peculiar en el entorno.",
  str_season_mission_desc_8001012 = "Después de sus ocupadas actividades, la sedienta Eve se dirigió al pozo para beber, pero notó algo peculiar en el entorno.",
  str_season_mission_desc_8001013 = "Eve levantó la cabeza, suspirando por el clima del día, solo para ver algo desconocido cerca...",
  str_season_mission_desc_8001014 = "Eve levantó la cabeza, suspirando por el clima del día, solo para ver algo desconocido cerca...",
  str_season_mission_desc_8001015 = "Eve luchó por quitarse de encima al gran sabueso pelirrojo, pero tan pronto como llegó a la entrada de Tail Street, escuchó gritos urgentes de la gente a su alrededor...",
  str_season_mission_desc_8001016 = "Eve luchó por quitarse de encima al gran sabueso pelirrojo, pero tan pronto como llegó a la entrada de Tail Street, escuchó gritos urgentes de la gente a su alrededor...",
  str_season_mission_desc_8001017 = "En ese momento, Eve no tuvo más opción que seguir los pasos de otro \"Eve\", adentrándose más profundo en Tail Street.",
  str_season_mission_desc_8001018 = "En ese momento, Eve no tuvo más opción que seguir los pasos de otro \"Eve\", adentrándose más profundo en Tail Street.",
  str_season_mission_desc_8001019 = "¿Por qué habría otro \"yo\" en este mundo? La mente de Eve estaba en turbulencia, llena de confusión y desorden.",
  str_season_mission_desc_8001020 = "¿Por qué habría otro \"yo\" en este mundo? La mente de Eve estaba en caos, llena de confusión y desorden.",
  str_season_mission_desc_8001021 = "En lo profundo de Tail Street, hay una habitación que Eve nunca ha encontrado antes, y dentro de ella, parece que una mujer está cautiva...?",
  str_season_mission_desc_8001022 = "En las profundidades de Tail Street, hay una habitación que Eve nunca ha encontrado antes, y dentro de ella, parece que una mujer está cautiva...?",
  str_season_mission_desc_8001023 = "Eve nunca había considerado dejar su tranquila casita, pero ahora se encuentra frente a una decisión que no puede evitar.",
  str_season_mission_desc_8001024 = "Eve nunca había considerado dejar su tranquila casita, pero ahora se encuentra frente a una decisión que no puede evitar.",
  str_season_mission_desc_8001025 = "Mientras caminaba, Eve perdió la noción de qué tan lejos había llegado, y el aire se volvió aún más seco y caliente que el abrasador Desierto de Rediesel...",
  str_season_mission_desc_8001026 = "Mientras caminaba, Eve perdió la noción de qué tan lejos había llegado, y el aire se volvió aún más seco y caliente que el abrasador Desierto de Rediesel...",
  str_season_mission_desc_8001027 = "El camino que \"Eve\" señaló no solo es duro, sino también acechado por Eclipsites. Eve duda, sin saber si debe seguir avanzando.",
  str_season_mission_desc_8001028 = "El camino que \"Eve\" señaló no solo es duro, sino también acechado por Eclipsites. Eve duda, sin saber si debe seguir avanzando.",
  str_season_mission_desc_8001029 = "Con la decisión tomada, Eve avanza con la cabeza en alto!",
  str_season_mission_desc_8001030 = "Con la decisión tomada, Eve avanza con la cabeza en alto!",
  str_season_mission_desc_8001031 = "¡Cuidado con la ardiente lava que se agita justo al lado de tus pies en el lecho del río! ¡No caigas!",
  str_season_mission_desc_8001032 = "¡Cuidado con la ardiente lava que se agita justo al lado de tus pies en el lecho del río! ¡No caigas!",
  str_season_mission_desc_8001033 = "Eve divisó \"Eve\" en la distancia... ¿Podría estar allí la respuesta definitiva?",
  str_season_mission_desc_8001034 = "Eve divisó \"Eve\" en la distancia... ¿Podría estar allí la respuesta definitiva?",
  str_season_mission_desc_8001035 = "Por fin... finalmente, llegué al lugar donde se encuentra \"Eve\". ¿Qué tipo de respuesta nos espera?",
  str_season_mission_desc_8001036 = "Por fin... finalmente, llegué al lugar donde se encuentra \"Eve\". ¿Qué tipo de respuesta nos espera?",
