  str_season_treasure_bubble_info_1_1 = "¿Qué me pasa? Mi cabeza da vueltas...\nPero espera... ¿hay alguien aquí?",
  str_season_treasure_bubble_info_2_1 = "Descubrí el primer fragmento del bloc de dibujo!\nPero cuando intenté unirlo, no parecía encajar... ¿Está mal este?",
  str_season_treasure_bubble_info_3_1 = "Otro fragmento. Una maceta vacía. Necesito encontrar la cosa adecuada para plantar en ella para una cosecha...",
  str_season_treasure_bubble_info_4_1 = "¿Se supone que la sombra debe encajar aquí?\n¡Ah! ¡Está en el otro lado!",
  str_season_treasure_bubble_info_5_1 = "¡Uf! ¿Cómo llegó esta taza de té aquí?\nAhora que tengo el agua, realmente quiero intentar preparar un té negro.",
  str_season_treasure_bubble_info_6_1 = "¡Tropezamos con una criatura ultra-rara!\nEl destino debió habernos llevado a cruzar caminos.",
  str_season_treasure_bubble_info_7_1 = "El sabor nostálgico y familiar...",
  str_season_treasure_bubble_info_11_1 = "Sostenerlo me hace sentir tan reconfortado. Mayserá útil en mi viaje.",
  str_season_treasure_bubble_info_12_1 = "Espera, ¿quién era esa persona que me llamó justo ahora...?",
  str_season_treasure_bubble_info_14_1 = "¡Encontré otro fragmento de bloc de dibujo!",
  str_season_treasure_bubble_info_15_1 = "¡Debo proteger esta semilla!\n¡Necesito encontrar el lugar perfecto para plantarla!",
  str_season_treasure_bubble_info_16_1 = "Tan hermoso, tan gratis...",
  str_season_mission_bubble_info_2_1 = "¿Esa sombra puede invocar Eclipsites?\nAhora no puedo simplemente ignorarlo, ¿verdad?",
  str_season_mission_bubble_info_4_1 = "¡Oye, espera! ¡No huyas!",
  str_season_mission_bubble_info_9_1 = "¿Dónde... me está llevando ella?",
  str_season_mission_bubble_info_10_1 = "Está justo adelante, y parece que está esperando a que me acerque, ¿no?",
  str_season_gear_bubble_info_1_1 = "El camino está bloqueado por la puerta...\n¡Esa cosa al final de Tail Street podría ser útil!",
  str_season_gear_bubble_info_1_2 = "¿Qué nos espera... hacia dónde nos lleva?",
